#define CROW_HIP_ROLL_LIBRARY
#include "../crow-v15-hip-roll-strong-drive-prototype-20261111/probe.cpp"
#include <array>
#include <iomanip>
static std::array<double,3> cross3(const std::array<double,3>&a,const std::array<double,3>&b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
static std::array<double,3> rotate3(const std::array<double,4>&q,const std::array<double,3>&v){std::array<double,3> u{q[0],q[1],q[2]};auto t=cross3(u,v);for(auto&x:t)x*=2.;auto z=cross3(u,t);return {v[0]+q[3]*t[0]+z[0],v[1]+q[3]*t[1]+z[1],v[2]+q[3]*t[2]+z[2]};}
int main(){try{auto robot=hipRollModel();need(robot.mechanics.joints.at(4).axis0.y==1.f && robot.mechanics.joints.at(5).axis0.y==-1.f,"unexpected axes");robot.mechanics.joints.at(5).axis0.y=1.f;const auto&m=robot.mechanics;std::cout<<std::setprecision(17);for(unsigned i=0;i<m.bodies.size();++i){const auto &b=m.bodies[i];std::cout<<i<<" "<<m.bodyNames[i]<<" "<<b.massAndInverseMass.x<<" "<<b.dampingAndSpeedLimits.x<<" "<<b.dampingAndSpeedLimits.y<<"\n";} int lane,step;while(std::cin>>lane>>step){std::vector<double> q(m.defaultQ.size()),v(m.defaultV.size());for(auto&x:q)need(bool(std::cin>>x),"missing q");for(auto&x:v)need(bool(std::cin>>x),"missing v");std::vector<ArticulatedBodyKinematics> k(m.bodies.size());need(computeArticulatedBodyKinematics(m,0,q,v,k).succeeded(),"FK failed");double mass=0;std::array<double,3> c{},cv{};for(unsigned i=0;i<k.size();++i){double w=m.bodies[i].massAndInverseMass.x;mass+=w;for(int j=0;j<3;++j){c[j]+=w*k[i].centerOfMassPosition[j];cv[j]+=w*k[i].linearVelocity[j];}}for(int j=0;j<3;++j){c[j]/=mass;cv[j]/=mass;}std::array<double,3> H{};for(unsigned i=0;i<k.size();++i){const auto&b=m.bodies[i];const auto&o=k[i].orientation;std::array<double,4> inv{-o[0],-o[1],-o[2],o[3]};auto w=rotate3(inv,k[i].angularVelocity);std::array<double,3> iw{b.inertiaRow0.x*w[0]+b.inertiaRow0.y*w[1]+b.inertiaRow0.z*w[2],b.inertiaRow1.x*w[0]+b.inertiaRow1.y*w[1]+b.inertiaRow1.z*w[2],b.inertiaRow2.x*w[0]+b.inertiaRow2.y*w[1]+b.inertiaRow2.z*w[2]};auto spin=rotate3(o,iw);std::array<double,3> r{},p{};for(int j=0;j<3;++j){r[j]=k[i].centerOfMassPosition[j]-c[j];p[j]=b.massAndInverseMass.x*(k[i].linearVelocity[j]-cv[j]);}auto orbital=cross3(r,p);for(int j=0;j<3;++j)H[j]+=spin[j]+orbital[j];}double damp=0; for(unsigned i=0;i<k.size();++i){const auto& b=m.bodies[i]; const auto& x=k[i]; double dx=x.centerOfMassPosition[0]-c[0],dy=x.centerOfMassPosition[1]-c[1]; double fx=-b.dampingAndSpeedLimits.x*x.linearVelocity[0],fy=-b.dampingAndSpeedLimits.x*x.linearVelocity[1]; damp+=dx*fy-dy*fx-b.dampingAndSpeedLimits.y*x.angularVelocity[2];}std::cout<<"D "<<lane<<" "<<step<<" "<<damp<<std::endl;}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
